typedef struct {
    uint64_t key;
    uint8_t value;
} z_t2031_entry_t;

typedef struct z_t2031_t {
    uint32_t length;
    uint32_t capacity;
    uint32_t* indices;
    z_t2031_entry_t* entries;
} z_t2031_t;

